Arguments: {"cwd":null,"code":"const tabId = 248688717;

const checkAll = await browserjs(tabId, async () => {
  // Check every month from 2026-09 to 2027-12
  const availableDates = [];
  const statusSummary = {};

  const months = [];
  let y = 2026, m = 9;
  while (y < 2028) {
    const mStr = m < 10 ? `0${m}` : `${m}`;
    months.push(`${y}-${mStr}-01T00:00:00.000Z`);
    m++;
    if (m > 12) {
      m = 1;
      y++;
    }
  }

  for (const start of months) {
    const res = await fetch(`/api/camps/availability/campground/232010/month?start_date=${encodeURIComponent(start)}`);
    if (!res.ok) continue;
    const json = await res.json();
    for (const [siteId, site] of Object.entries(json.campsites || {})) {
      for (const [dateStr, status] of Object.entries(site.availabilities || {})) {
        statusSummary[status] = (statusSummary[status] || 0) + 1;
        if (status === 'Available' || status === 'Open') {
          availableDates.push({ siteId, site: site.site, date: dateStr.slice(0, 10), status });
        }
      }
    }
  }

  return { availableDates, statusSummary };
});

console.log("Status summary across all months:", checkAll.statusSummary);
console.log("Available dates count:", checkAll.availableDates.length);
if (checkAll.availableDates.length > 0) {
  console.log("First 5 available dates:", checkAll.availableDates.slice(0, 5));
}
